  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $A$ and $B$ are independent with $P(A) = 0.3$ and $P(B) = 0.4$, then $P(A \cup B)$ is:', '["0.70","0.58","0.12","0.82"]'::jsonb, 1, '$P(A\cup B) = P(A) + P(B) - P(A)P(B) = 0.3 + 0.4 - 0.12 = 0.58$.', 'Additive Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $P(A \cap B) = 0.2$ and $P(B) = 0.5$, the conditional probability $P(A \mid B)$ is:', '["0.1","0.7","0.4","2.5"]'::jsonb, 2, '$P(A\mid B) = P(A\cap B)/P(B) = 0.2/0.5 = 0.4$.', 'Conditional Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A fair coin is tossed twice. The probability of at least one head is:', '["1/4","1/2","1","3/4"]'::jsonb, 3, '$1 - P(\text{no head}) = 1 - 1/4 = 3/4$.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'One card is drawn from a standard pack of 52. The probability that it is a king or a heart is:', '["4/13","17/52","1/2","3/13"]'::jsonb, 0, '$P(K) + P(H) - P(K\cap H) = \tfrac{4}{52} + \tfrac{13}{52} - \tfrac{1}{52} = \tfrac{16}{52} = \tfrac{4}{13}$.', 'Additive Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A bag holds 5 red and 3 blue balls. Two balls are drawn without replacement. The probability that both are red is:', '["25/64","5/14","5/8","1/4"]'::jsonb, 1, '$\tfrac{5}{8}\times\tfrac{4}{7} = \tfrac{20}{56} = \tfrac{5}{14}$.', 'Multiplication Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The probability of getting a number not greater than 6 on a fair die is:', '["0","1/3","1","1/6"]'::jsonb, 2, 'Every outcome is at most 6, so the event is certain.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Urn 1 holds 3 red and 2 blue balls; urn 2 holds 1 red and 4 blue. An urn is chosen at random and one ball is drawn. The probability that the ball is red is:', '["0.5","0.6","0.3","0.4"]'::jsonb, 3, 'Total probability: $0.5(0.6) + 0.5(0.2) = 0.4$.', 'Total Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In that experiment, given that the ball drawn is red, the probability that it came from urn 1 is:', '["0.75","0.60","0.50","0.25"]'::jsonb, 0, 'Bayes'' theorem: $\dfrac{0.5(0.6)}{0.5(0.6) + 0.5(0.2)} = \dfrac{0.3}{0.4} = 0.75$.', 'Bayes'' Theorem', false, 'second', 3),
