  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean of a binomial distribution with parameters $n$ and $p$ is:', '["$npq$","$np$","$n(n-1)pq$","$pq$"]'::jsonb, 1, 'The variance is $npq$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A fair die is thrown five times. The probability of getting exactly one six is:', '["0.3564","0.7854","0.4019","0.0234"]'::jsonb, 2, '$\binom{5}{1}\left(\tfrac{1}{6}\right)\left(\tfrac{5}{6}\right)^{4} = 0.4019$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A fair coin is tossed six times. The probability of exactly four heads is:', '["0.5742","0.5673","0.4532","0.2344"]'::jsonb, 3, '$\binom{6}{4}\left(\tfrac{1}{2}\right)^{6} = \tfrac{15}{64} = 0.2344$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For $X \sim \text{Bin}(10, 0.3)$, $P(X = 3)$ is:', '["0.2668","0.3000","0.0900","0.5000"]'::jsonb, 0, '$\binom{10}{3}(0.3)^{3}(0.7)^{7} = 0.2668$.', 'Binomial Distribution', false, 'second', 3),
