  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which distribution has its mean and variance both equal to $\lambda$?', '["Poisson","Exponential","Normal","Geometric"]'::jsonb, 0, 'For a Poisson variable, $E(X) = \mathrm{Var}(X) = \lambda$.', 'Poisson Distribution', false, 'second', 3),
